import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

        cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_DIM 32
#define THREAD_WORK_ROWS 4
#define THREAD_WORK_COLS 4
#define BLOCK_ROWS 8 // TILE_DIM / THREAD_WORK_ROWS
#define BLOCK_COLS 8 // TILE_DIM / THREAD_WORK_COLS

__global__ void matmul_kernel_fixed(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_DIM][TILE_DIM];
    __shared__ float Bs[TILE_DIM][TILE_DIM];

    int bx = blockIdx.x;
    int by = blockIdx.y;
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Each thread computes a THREAD_WORK_ROWS x THREAD_WORK_COLS sub-matrix of C.
    // The block is composed of BLOCK_ROWS x BLOCK_COLS threads.
    int thread_row = by * TILE_DIM + ty * THREAD_WORK_ROWS;
    int thread_col = bx * TILE_DIM + tx * THREAD_WORK_COLS;

    float Csub[THREAD_WORK_ROWS][THREAD_WORK_COLS] = {0.0f};

    for (int t = 0; t < (N + TILE_DIM - 1) / TILE_DIM; ++t) {
        // Load tiles into shared memory
        // Each thread now loads THREAD_WORK_ROWS * THREAD_WORK_COLS elements
        for (int i = 0; i < THREAD_WORK_ROWS; ++i) {
            int load_row = ty * THREAD_WORK_ROWS + i;
            int a_row = by * TILE_DIM + load_row;
            int a_col = t * TILE_DIM + tx;
             if(a_row < N && a_col < N){
                As[load_row][tx] = A[a_row * N + a_col];
            } else {
                As[load_row][tx] = 0.0f;
            }
        }
        for (int i = 0; i < THREAD_WORK_COLS; ++i) {
             int load_col = tx * THREAD_WORK_COLS + i;
             int b_row = t * TILE_DIM + ty;
             int b_col = bx * TILE_DIM + load_col;
             if(b_row < N && b_col < N){
                Bs[ty][load_col] = B[b_row * N + b_col];
             } else {
                Bs[ty][load_col] = 0.0f;
             }
        }


        __syncthreads();

        // Multiply tiles
        for (int k = 0; k < TILE_DIM; ++k) {
            for (int i = 0; i < THREAD_WORK_ROWS; i++) {
                for (int j = 0; j < THREAD_WORK_COLS; j++) {
                    Csub[i][j] += As[ty * THREAD_WORK_ROWS + i][k] * Bs[k][tx * THREAD_WORK_COLS + j];
                }
            }
        }
        __syncthreads();
    }


    // Write the sub-matrix to global memory
    for (int i = 0; i < THREAD_WORK_ROWS; i++) {
        for (int j = 0; j < THREAD_WORK_COLS; j++) {
            int c_row = thread_row + i;
            int c_col = thread_col + j;
            if (c_row < N && c_col < N) {
                C[c_row * N + c_col] = Csub[i][j];
            }
        }
    }
}


torch::Tensor matmul_forward(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 2, "A must be a 2D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be a 2D tensor");
    TORCH_CHECK(A.size(1) == B.size(0), "Matrix dimensions are incompatible for multiplication");

    int N = A.size(0);
    auto C = torch::empty({N, N}, A.options());

    dim3 threadsPerBlock(BLOCK_COLS, BLOCK_ROWS);
    dim3 numBlocks((N + TILE_DIM - 1) / TILE_DIM, (N + TILE_DIM - 1) / TILE_DIM);

    matmul_kernel_fixed<<<numBlocks, threadsPerBlock>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
